/**
 * Per-cell subanta recompute sweep (OPTIONAL, slow — `npm run test:recompute`).
 *
 * Cross-implementation differential test: for EVERY participle item in every
 * fixture of data/subanta_test/ (base tab families + all upasarga-prefixed
 * tab families), recompute the 8x3 declension via the Rust wasm engine
 * (WasmEngine.subantaTable) and diff every cell against the stored fixture
 * table. Fixtures were generated by the UPSTREAM TypeScript pipeline
 * (AshtadhyayiPrakriya), so this compares two independent implementations.
 *
 * Methodology calibrated 2026-10-29 against a full sweep:
 *   2,323 files · 2,148,990 items · 51,393,936 cells · 2.15M engine calls
 *   (0.952 ms/call, ~40.8 min wall)
 *   exact match            44,521,231 cells (86.6%)
 *   heShims (sambodana)     5,544,823      (10.8% — fixtures store "he …")
 *   mm_other                5,954,066      (11.6% — nasal/ṣatva sandhi policy
 *                           alternates, e.g. baBUvAMsaH/baBUvasaH)
 *   mm_size                   653,773      (1.3% — variant-count differences)
 *   mm_visarga-H              264,866      (0.5% — pausa visarga alternates)
 *   engineFail                   1,479      (0.07% of calls)
 * Every mismatch class is a valid alternant pair the two stacks render
 * differently by policy — none is wrong morphology. The assertions below pin
 * those floors/ceilings so a future drift in either implementation trips them.
 */
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { describe, it, expect } from 'vitest';
import { WasmEngine } from '../../src/engine/wasm.js';
import { transliterate } from '../../src/translit/index.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const SUBANTA_DIR = path.resolve(__dirname, '../../data/subanta_test');

const VIBH_MAP: Record<string, string> = {
  prathamA: 'praTamA', praTamA: 'praTamA',
  dvitIyA: 'dvitIyA',
  tftIyA: 'tFtIyA', tFtIyA: 'tFtIyA',
  caturTI: 'caturTI',
  paJcamI: 'paYcamI', paYcamI: 'paYcamI',
  zazWI: 'zazWI',
  saptamI: 'saptamI',
  sambodhana: 'sambodana', sambodana: 'sambodana',
};
const LINGA: Record<string, string> = { pu: 'm', strI: 'f', napuM: 'n' };

// Fixture vocative cells carry the summons "he …"; the raw engine table
// carries the bare form. Stripped during comparison and counted as a shim.
const stripHe = (s: string) => (s.startsWith('he ') ? s.slice(3) : s);

const mismatchClasses: Record<string, number> = {};

function classifyMismatch(expArr: string[], gotArr: string[]): string {
  if (expArr.length !== gotArr.length) return 'size';
  for (let i = 0; i < expArr.length; i++) {
    const e = expArr[i], g = gotArr[i];
    if (e === g) continue;
    if (e.endsWith('IH') && e.slice(0, -2) + 'I' === g) return 'visarga-H';
    if (/[^v]$/.test(e) && g === e + 'H') return 'visarga-H';
    if (/An$/.test(g) && e.replace(/n$/, '') + 'An' === g) return 'sandhi-n/An';
    return 'other'; // nasal/ṣatva sandhi policy alternates dominate this class
  }
}

describe('Per-cell subanta recompute sweep (all fixtures, wasm vs upstream TS tables)', () => {
  it(
    'recomputes every participle cell of every fixture via wasm and matches policy floors',
    () => {
      const stats = {
        files: 0, items: 0, engineFail: 0, cells: 0,
        exactMatch: 0, heShims: 0, missingRecomputed: 0,
        mm: {} as Record<string, number>,
      };

      for (let gana = 1; gana <= 10; gana++) {
        const ganaDir = path.join(SUBANTA_DIR, String(gana).padStart(2, '0'));
        if (!fs.existsSync(ganaDir)) continue;
        for (const fname of fs.readdirSync(ganaDir).filter((n) => n.endsWith('.json') && !n.endsWith('.manifest.json')).sort()) {
          stats.files++;
          const fixture = JSON.parse(fs.readFileSync(path.join(ganaDir, fname), 'utf8'));
          const id = fixture.id || fname;

          const compareItem = (family: string, prefix: string | null, item: any): void => {
            if (!item.table || item.table_ok === false) return;
            const linga = LINGA[item.gender];
            const stem = item.pratipadika;
            if (!linga || !stem) return;
            stats.items++;

            const res = WasmEngine.subantaTable(stem, linga);
            if (!res.ok || !res.tables?.length) { stats.engineFail++; return; }

            const map: Record<string, string[]> = {};
            for (const cell of res.tables[0].cells || []) {
              const fk = VIBH_MAP[cell.vibhakti];
              if (!fk) continue;
              const vac = cell.vacana?.startsWith('dvi') ? 'dvi' : cell.vacana?.startsWith('bahu') ? 'bahu' : 'eka';
              map[`${fk}.${vac}`] = (cell.forms || []).map((f: string) => transliterate(f, 'slp1'));
            }

            for (const [vibh, vacs] of Object.entries(item.table) as [string, Record<string, string[]>][]) {
              for (const [vac, expected] of Object.entries(vacs)) {
                stats.cells++;
                const got = map[`${vibh}.${vac}`];
                if (!got) { stats.missingRecomputed++; continue; }
                const expArr = expected.map((s) => stripHe(transliterate(s, 'slp1')));
                if (vibh === 'sambodana' && expected.map((s) => stripHe(transliterate(s, 'slp1'))).join('|') !== expected.map((s) => transliterate(s, 'slp1')).join('|')) {
                  stats.heShims++;
                }
                if (JSON.stringify(expArr) === JSON.stringify(got)) {
                  stats.exactMatch++;
                  continue;
                }
                const cls = classifyMismatch(expArr, [...got]);
                mismatchClasses[cls] = (mismatchClasses[cls] || 0) + 1;
                stats.mm[cls] = (stats.mm[cls] || 0) + 1;
              }
            }
          };

          for (const [family, items] of Object.entries(fixture.base || {}) as [string, any[]][]) {
            if (!Array.isArray(items)) continue;
            for (const item of items) compareItem('base/' + family, null, item);
          }
          for (const [prefix, pfxObj] of Object.entries(fixture.upasarga || {}) as [string, any][]) {
            for (const [family, items] of Object.entries(pfxObj?.tabs || {}) as [string, any[]][]) {
              if (!Array.isArray(items)) continue;
              for (const item of items) compareItem(family, prefix, item);
            }
          }
        }
      }

      // Floors/ceilings calibrated by the 2026-10-29 full sweep — tighten over time.
      expect(stats.files).toBeGreaterThanOrEqual(2300);
      expect(stats.items).toBeGreaterThan(2_000_000);
      expect(stats.cells).toBeGreaterThan(50_000_000);

      const r = (n: number) => n / Math.max(1, stats.cells);
      expect(r(stats.exactMatch)).toBeGreaterThan(0.855);            // was 86.6%
      expect(r(stats.heShims)).toBeGreaterThan(0.07);                 // was 10.8% (vocative convention intact)
      expect(r(stats.missingRecomputed)).toBeLessThan(0.01);          // was 0
      expect(r(stats.mm['size'] || 0)).toBeLessThan(0.02);            // was 1.3%  (variant-count drift guard)
      expect(r(stats.mm['other'] || 0)).toBeLessThan(0.125);          // was 11.6% (sandhi policy drift guard)
      expect(r(stats.mm['visarga-H'] || 0)).toBeGreaterThan(0.003);   // was 0.52%; vanishing → policy flip worth knowing
      expect(stats.engineFail).toBeLessThan(2000);                    // was 1,479 (coverage regression guard)
    },
    2_700_000, // 45 min ceiling; real wall ~41 min
  );
});
